/* ทะเบียนตัวอย่างสำหรับทดสอบ `check-ทะเบียนปลายเปิด.mjs` — **ข้อมูลล้วน ไม่มีผลข้างเคียง**
   (รูปเดียวกับที่ขอให้ฝั่งท่อแยกไฟล์ออกมา) · โหมดเลือกด้วย env `REGISTRY_MODE` */
const โหมด = process.env.REGISTRY_MODE || 'ตรง'
export const ปลายเปิด = {
  /* ช่องที่จอ `/core/sales` อ่านจริง (statusesAll มีอยู่ในไฟล์นั้นแน่) */
  'orders.statusesAll': { ปลายเปิด: true, ใครอ่าน: 'gucut-next · /core/sales', อ่านเป็น: 'สร้างรายชื่อแท็บ' },
  /* ทิศ ①: จดว่ามีคนอ่าน แต่ชื่อช่องไม่มีในจอเลย */
  ...(โหมด === 'ทิศ1'
    ? { 'orders.ช่องที่จอเลิกอ่านแล้ว': { ปลายเปิด: true, ใครอ่าน: 'gucut-next · /core/sales', อ่านเป็น: 'เรนเดอร์เป็นแถว' } }
    : {}),
  /* ทิศ ②: จดว่าไม่มีใครอ่าน แต่จออ่านอยู่จริง */
  ...(โหมด === 'ทิศ2'
    ? { 'orders.statusesAllError': { ปลายเปิด: false, ใครอ่าน: 'ไม่มี (วัด 14 ต.ค. 2569)', อ่านเป็น: '—' } }
    : {}),
  /* 🆕 ชนิดผู้อ่าน (ฝั่งท่อแยกเป็นฟิลด์ 14 ต.ค. 2569) — สามโหมดสำหรับกิ่งใหม่ของด่าน */
  ...(โหมด === 'ชนิดต่ำกว่าจริง'
    /* จดว่าเป็นด่าน/ตัววัด แต่จอก็อ่านด้วย ⇒ ความเสี่ยง UI ไม่ถูกจด */
    ? { 'orders.statusesAll': { ปลายเปิด: false, ใครอ่าน: 'gucut-next · ตัววัด', ชนิดผู้อ่าน: 'ด่าน/ตัววัด', อ่านเป็น: 'คิดเลข' } }
    : {}),
  ...(โหมด === 'ด่านเลิกอ่าน'
    ? { 'orders.ช่องที่ไม่มีใครอ่านเลย': { ปลายเปิด: false, ใครอ่าน: 'ตัววัด', ชนิดผู้อ่าน: 'ด่าน/ตัววัด', อ่านเป็น: 'คิดเลข' } }
    : {}),
  ...(โหมด === 'libไม่ตรง'
    ? { 'orders.ช่องที่ไม่อยู่ใน lib': { ปลายเปิด: true, ใครอ่าน: 'lib', ชนิดผู้อ่าน: 'lib ที่จอเรียก', อ่านเป็น: 'ส่งต่อออกจอ' } }
    : {}),
  /* 🔴 ขอบคำ: จดว่า `byStatus` ไม่มีใครอ่าน · เนื้อที่ถูกกวาดมีแต่ `byStatusFiltered`
     ⇒ ถ้าด่านใช้ `includes` จะนับว่าเอ่ย ⇒ **แดงลวง** (ฝั่งท่อยิงตรวจแล้วส่งมาเตือน) */
  ...(โหมด === 'ขอบคำ'
    ? { 'orders.byStatus': { ปลายเปิด: false, ใครอ่าน: 'ไม่มี (ทดสอบขอบคำ)', อ่านเป็น: null } }
    : {}),
  /* 🔴 ทะเบียนขัดกันเอง: ไม่มีใครอ่าน แต่ระบุชนิดผู้อ่านไว้ */
  ...(โหมด === 'ขัดกันเอง'
    ? { 'orders.ช่องขัดกัน': { ปลายเปิด: true, ใครอ่าน: 'ไม่มี (วัดแล้ว)', ชนิดผู้อ่าน: 'ด่าน/ตัววัด', อ่านเป็น: null } }
    : {}),
  /* ค่าเก่าแบบสตริง — ตรวจไม่ได้ และต้องถูกนับให้เห็น */
  'transfers.byKind': 'ชนิดใบโอน — ZORT เพิ่มชนิดได้',
}
